13: static void stencil_step(int x0, int x1, int y0, int y1, int z0, int z1, int Nx, int Ny, int Nz, const float coef[4],
14:                          const float vsq[], const float Ain[], float Aout[]) {
15:     int Nxy = Nx * Ny;
16: 
17:     // All threads in the persistent team encounter this worksharing loop.
18:     // Its implicit barrier keeps the next stencil step from reading unfinished output.
19:     #pragma omp for schedule(static)
20:     for (int z = z0; z < z1; ++z) {
21:         for (int y = y0; y < y1; ++y) {
22:             for (int x = x0; x < x1; ++x) {
23:                 int index = (z * Nxy) + (y * Nx) + x;
24: #define A_cur(x, y, z) Ain[index + (x) + ((y)*Nx) + ((z)*Nxy)]
25: #define A_next(x, y, z) Aout[index + (x) + ((y)*Nx) + ((z)*Nxy)]
26:                 float div = coef[0] * A_cur(0, 0, 0) +
27:                             coef[1] * (A_cur(+1, 0, 0) + A_cur(-1, 0, 0) + A_cur(0, +1, 0) + A_cur(0, -1, 0) +
28:                                        A_cur(0, 0, +1) + A_cur(0, 0, -1)) +
29:                             coef[2] * (A_cur(+2, 0, 0) + A_cur(-2, 0, 0) + A_cur(0, +2, 0) + A_cur(0, -2, 0) +
30:                                        A_cur(0, 0, +2) + A_cur(0, 0, -2)) +
31:                             coef[3] * (A_cur(+3, 0, 0) + A_cur(-3, 0, 0) + A_cur(0, +3, 0) + A_cur(0, -3, 0) +
32:                                        A_cur(0, 0, +3) + A_cur(0, 0, -3));
33: 
34:                 A_next(0, 0, 0) = 2 * A_cur(0, 0, 0) - A_next(0, 0, 0) + vsq[index] * div;
35:             }
36:         }
37:     }
38: }
